      <div class="advisor-quick-spec"><span><b>CPU</b>${esc(partOf('cpu',items).name)}</span><span><b>GPU</b>${esc(partOf('gpu',items).name)}</span><span><b>RAM</b>${esc(partOf('ram',items).name)}</span></div>
